def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def candies(M, N):
    if gcd(M, N) != 1:
        return 0  # M and N are not coprime, so this should not happen as per the contract.

    reachable = [False] * (M * N + 1)
    reachable[0] = True

    for i in range(M * N + 1):
        if reachable[i]:
            if i + M <= M * N:
                reachable[i + M] = True
            if i + N <= M * N:
                reachable[i + N] = True

    return reachable.count(False) - 1  # Subtract 1 to exclude the starting point at index 0

# Example usage:
# print(candies(2, 5))  # Output: 2
# print(candies(2, 7))  # Output: 3
# print(candies(25, 7)) # Output: 72
